	if err == nil {
		return ""
	}
	return manifestDecodeTypePattern.ReplaceAllStringFunc(err.Error(), func(match string) string {
		name := strings.TrimPrefix(match, "type room.")
		if label, ok := manifestDecodeTypeLabels[name]; ok {
			return label
		}
		return "the manifest"
	})
