func (m *Mesh) removePending(want *pendingPair) {
	m.mu.Lock()
	defer m.mu.Unlock()
	if m.closed || m.ctx.Err() != nil {
		return
	}
	m.removePendingLocked(want)
}

func (m *Mesh) removePendingLocked(want *pendingPair) {
	for index, pending := range m.pending {
		if pending != want {
			continue
		}
		copy(m.pending[index:], m.pending[index+1:])
		m.pending[len(m.pending)-1] = nil
		m.pending = m.pending[:len(m.pending)-1]
		return
	}
}

func (m *Mesh) removePendingPairs(pairs []*meshPair) {
	if len(pairs) == 0 {
		return
	}
	m.mu.Lock()
	defer m.mu.Unlock()
	if m.closed || m.ctx.Err() != nil {
		return
	}
	m.removePendingPairsLocked(pairs)
}

func (m *Mesh) removePendingPairsLocked(pairs []*meshPair) {
	wanted := make(map[*meshPair]struct{}, len(pairs))
	for _, pair := range pairs {
		if pair != nil {
			wanted[pair] = struct{}{}
		}
	}
	if len(wanted) == 0 {
		return
	}
	original := m.pending
	kept := original[:0]
	for _, pending := range original {
		if pending == nil || pending.pair == nil {
			continue
		}
		if _, exists := wanted[pending.pair]; exists {
			continue
		}
		kept = append(kept, pending)
	}
	for index := len(kept); index < len(original); index++ {
		original[index] = nil
	}
	m.pending = kept
}

func (m *Mesh) removeClosingPairs(pairs []*meshPair) {
	if len(pairs) == 0 {
		return
	}
	m.mu.Lock()
	defer m.mu.Unlock()
	wanted := make(map[*meshPair]struct{}, len(pairs))
	for _, pair := range pairs {
		if pair != nil {
			wanted[pair] = struct{}{}
		}
	}
	if len(wanted) == 0 {
		return
	}
	original := m.closing
	kept := original[:0]
	for _, pair := range original {
		if pair == nil {
			continue
		}
		if _, exists := wanted[pair]; exists {
			continue
		}
		kept = append(kept, pair)
	}
	for index := len(kept); index < len(original); index++ {
		original[index] = nil
	}
	m.closing = kept
}

func closeMeshPairs(pairs []*meshPair) error {
	var closeErr error
	for index := len(pairs) - 1; index >= 0; index-- {
		if pairs[index] == nil {
			continue
		}
		closeErr = errors.Join(closeErr, pairs[index].close())
	}
	return closeErr
}

