				m.setError(err)
				m.cancel()
				return
			}
			if err := m.enqueueFrame(m.ctx, frame, sources); err != nil {
				if errors.Is(err, ErrMixerClosed) && m.ctx.Err() != nil {
					return
				}
				return
			}
		}
	}
}

