func (m *PCM16Mixer) enqueueFrame(ctx context.Context, frame []byte, sources []string) error {
	if m == nil {
		return ErrMixerClosed
	}
	if ctx == nil {
		ctx = context.Background()
	}
	m.outputSourcesMu.Lock()
	m.outputSources = append(m.outputSources, append([]string(nil), sources...))
	m.outputSourcesMu.Unlock()
	removeSources := func() {
		m.outputSourcesMu.Lock()
		if len(m.outputSources) > 0 {
			m.outputSources = m.outputSources[:len(m.outputSources)-1]
		}
		m.outputSourcesMu.Unlock()
	}
	select {
	case m.out <- frame:
		return nil
	case <-ctx.Done():
		removeSources()
		return ctx.Err()
	case <-m.ctx.Done():
		removeSources()
		return m.writeTerminationError()
	}
}

func (m *PCM16Mixer) popOutputSources() []string {
	if m == nil {
		return nil
	}
	m.outputSourcesMu.Lock()
	defer m.outputSourcesMu.Unlock()
	if len(m.outputSources) == 0 {
		return nil
	}
	sources := m.outputSources[0]
	copy(m.outputSources, m.outputSources[1:])
	m.outputSources[len(m.outputSources)-1] = nil
	m.outputSources = m.outputSources[:len(m.outputSources)-1]
	return sources
}

func (m *PCM16Mixer) setError(err error) {
	if err == nil {
		return
	}
	m.mu.Lock()
	if m.err == nil {
		m.err = err
		m.signalWritersLocked()
	}
	m.mu.Unlock()
}

func (m *PCM16Mixer) signalWritersLocked() {
	if m.writeWake == nil {
		m.writeWake = make(chan struct{})
		return
	}
	close(m.writeWake)
	m.writeWake = make(chan struct{})
}// signalWritersLocked wakes every writer that observed the previous input
// occupancy. Replacing the channel lets a writer safely go back to sleep
// without missing a signal that happened between its unlock and select.

func (m *PCM16Mixer) writeTerminationError() error {
	m.mu.Lock()
	defer m.mu.Unlock()
	if m.err != nil {
		return m.err
	}
	if m.closed {
		return ErrMixerClosed
	}
	if err := m.ctx.Err(); err != nil {
		return err
	}
	return ErrMixerClosed
}

func (m *PCM16Mixer) queueStats(queuedBytes, capacityBytes int) PCM16QueueStats {
	return PCM16QueueStats{Bytes: queuedBytes, CapacityBytes: capacityBytes, Frames: queueFrameCount(queuedBytes, m.frameBytes), CapacityFrames: queueFrameCount(capacityBytes, m.frameBytes), Duration: pcm16Duration(queuedBytes, m.format), CapacityDuration: pcm16Duration(capacityBytes, m.format)}
}

func queueFrameCount(bytes, frameBytes int) int {
	if bytes <= 0 || frameBytes <= 0 {
		return 0
	}
	return (bytes-1)/frameBytes + 1
}

