	if owner, ok := session.(RTCMediaSession); ok {
		return owner.RTCMedia(), true
	}
	if forwarder, ok := session.(rtcMediaSessionForwarder); ok {
		return forwarder.rtcMedia()
	}
	return RTCMediaEndpoints{}, false
}

