	controlCount := 0
	for _, step := range scenario.Steps {
		if step.Interrupt != nil || step.Cancel != nil {
			controlCount++
		}
	}
	if controlCount == 0 {
		return nil
	}
	return &browserConversationInterruptionController{run: run, tracker: tracker, scenario: scenario, audio: cloneBrowserConversationAudioMap(audio), channel: make(chan ScheduledAudioInput, len(scenario.Steps)), triggered: make(map[string]bool)}
