	if c == nil || len(input.PCM) == 0 {
		return false
	}
	input.PCM = append([]byte(nil), input.PCM...)
	c.mu.Lock()
	defer c.mu.Unlock()
	if c.closed {
		return false
	}
	select {
	case c.channel <- input:
		return true
	default:
