func (r *sessionReplayRenderer) Write(data []byte) (int, error) {
	if err := r.finishTranscript(); err != nil {
		return 0, err
	}
	n, err := r.out.Write(data)
	if err == nil && n != len(data) {
		err = io.ErrShortWrite
	}
	if err == nil {
		r.transcriptJustClosed = false
	}
	return n, err
}

