func writeRecordingSpool(file *os.File, data []byte) error {
	if file == nil {
		return errors.New("recording spool is not open")
	}
	for len(data) > 0 {
		written, err := file.Write(data)
		if err != nil {
			return err
		}
		if written <= 0 || written > len(data) {
			return io.ErrShortWrite
		}
		data = data[written:]
	}
	return nil
}

