	l.pending = make(map[string][]roomAudioIngressAdmission)
	l.mu.Unlock()
	for _, admission := range pending {
		if admission.contentful {
			l.record(admission.sourcePeer, roomAudioIngressDispositionRejected, reason, admission.byteCount)
		}
	}
}

