func newRawPCMWriter(path string) (*rawPCMWriter, error) {
	file, err := os.OpenFile(path, os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0o600)
	if err != nil {
		return nil, err
	}
	return &rawPCMWriter{path: path, file: file}, nil
