	v...(truncated)

func (r *sessionComposedRTCRuntime) Close() error {
	r.closeOnce.Do(func() {
		r.mu.Lock()
		r.closed = true
		cancel := r.cancel
		startDone := r.startDone
		media, dataPlane, signaling := r.media, r.dataPlane, r.signaling
		r.media = nil
		r.dataPlane = nil
		r.signaling = nil
		r.cancel = nil
		r.mu.Unlock()
		if cancel != nil {
			cancel()
		}
		if startDone != nil {
			<-startDone
		}
		r.closeErr = closeSessionRTCResources(media, dataPlane, signaling)
		level := "info"
		if r.closeErr != nil {
			level = "error"
		}
		r.observe("closed", "close", level)
	})
	return r.closeErr
}

func (r *sessionComposedRTCRuntime) observe(event, phase, level string) {
	if r == nil {
		return
	}
	fields := observability.Fields{"transport": r.selection.Transport, "phase": phase, "event": event}
	_ = observability.TrySample(context.Background(), r.metricSampler, observability.MetricSample{Name: "session.rtc.lifecycle", Kind: "counter", Value: 1, Unit: "events", Fields: fields})
	_ = observability.TryLog(context.Background(), r.logger, observability.LogRecord{Level: level, Message: "session RTC runtime " + event, Fields: fields})
}

func closeSessionRTCResources(media sharedaudio.InboundMedia, dataPlane SessionRTCDataPlane, signaling rtc.Signaling) error {
	return errors.Join(closeSessionRTCResource(media), closeSessionRTCResource(dataPlane), closeSessionRTCResource(signaling))
}

func closeSessionRTCResource(resource interface{ Close() error }) error {
	if resource == nil {
		return nil
	}
	return resource.Close()
}

