func (s *interruptibleAudioSource) Close() error {
	if s == nil {
		return nil
	}
	s.closeOnce.Do(func() {
		s.mu.Lock()
		s.closed = true
		s.mu.Unlock()
		if s.input != nil {
			s.closeErr = s.input.Close()
		}
		if s.source != nil {
			s.closeErr = errors.Join(s.closeErr, s.source.Close())
